CREATE OR REPLACE PROCEDURE sp(
  arg1 VARCHAR2,
  arg2 NUMBER,
  arg3 VARCHAR2,
  arg4 VARCHAR2
) AS
  v_mascot_count NUMBER;
  v_budgeted_avg  "budget"."Budgeted"%TYPE;
  v_enroll_avg    "School"."Enrollment"%TYPE;
  v_updated_count NUMBER := 0;
BEGIN
  SAVEPOINT sp_savepoint;

  -- Mascot match count, before any update
  SELECT COUNT(*) INTO v_mascot_count
    FROM "School"
   WHERE "Mascot" = arg3;

  IF v_mascot_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20002,
      'No School record matches the mascot; budget updates skipped');
  END IF;

  -- Averages, before any row is updated
  SELECT AVG("Budgeted") INTO v_budgeted_avg FROM "budget";
  SELECT AVG("Enrollment") INTO v_enroll_avg FROM "School";

  -- Budget pass
  FOR rec IN (SELECT "School_id", "Year", "Budgeted",
                     "total_budget_percent_budgeted",
                     "Budget_invested_percent"
                FROM "budget") LOOP
    IF rec."Budget_invested_percent" = arg1
       AND rec."total_budget_percent_budgeted" <= arg2
       AND rec."Budgeted" > v_budgeted_avg THEN
      UPDATE "budget"
         SET "total_budget_percent_budgeted" = arg2
       WHERE "School_id" = rec."School_id"
         AND "Year" = rec."Year";
      v_updated_count := v_updated_count + 1;
    END IF;
  END LOOP;

  -- School pass
  FOR rec IN (SELECT "School_id", "Mascot", "Enrollment"
                FROM "School") LOOP
    IF rec."Mascot" = arg3
       AND rec."Enrollment" > v_enroll_avg THEN
      UPDATE "School"
         SET "Location" = arg4
       WHERE "School_id" = rec."School_id";
      v_updated_count := v_updated_count + 1;
    END IF;
  END LOOP;

  IF v_updated_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK TO sp_savepoint;
    RAISE;
END sp;

