DECLARE
  e_noward EXCEPTION; PRAGMA EXCEPTION_INIT(e_noward, -20002);
  e_noupd EXCEPTION; PRAGMA EXCEPTION_INIT(e_noupd, -20001);
BEGIN
  DBMS_OUTPUT.PUT_LINE('--- Test 1: successful run (budget row updated, school below avg) ---');
  sp('71.3', 5, 'Cavaliers', 'Testville');
  FOR r IN (SELECT "School_id", "Year", "total_budget_percent_budgeted" FROM "budget" WHERE "School_id"=1 AND "Year"=2003) LOOP
    DBMS_OUTPUT.PUT_LINE('budget row pct now: ' || r."total_budget_percent_budgeted");
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Cavaliers location: ' || (SELECT "Location" FROM "School" WHERE "Mascot"='Cavaliers'));

  DBMS_OUTPUT.PUT_LINE('--- Test 2: no school match error ---');
  BEGIN
    sp('71.3', 5, 'NOSUCHMASCOT', 'X');
  EXCEPTION WHEN e_noward THEN
    DBMS_OUTPUT.PUT_LINE('Got -20002: ' || SQLERRM);
  END;
  DBMS_OUTPUT.PUT_LINE('budget row pct after rollback: ' || (SELECT "total_budget_percent_budgeted" FROM "budget" WHERE "School_id"=1 AND "Year"=2003));

  DBMS_OUTPUT.PUT_LINE('--- Test 3: mascot matches (above avg) but no budget row matches -> -20001 with rollback ---');
  BEGIN
    sp('999.9', 5, 'Falcons', 'Glenndale');
  EXCEPTION WHEN e_noupd THEN
    DBMS_OUTPUT.PUT_LINE('Got -20001: ' || SQLERRM);
  END;
  DBMS_OUTPUT.PUT_LINE('Falcons location after rollback: ' || (SELECT "Location" FROM "School" WHERE "Mascot"='Falcons'));

  DBMS_OUTPUT.PUT_LINE('--- Test 4: both passes update; school above avg ---');
  sp('71.3', 5, 'Falcons', 'Glenndale');
  DBMS_OUTPUT.PUT_LINE('Falcons location now: ' || (SELECT "Location" FROM "School" WHERE "Mascot"='Falcons'));
  DBMS_OUTPUT.PUT_LINE('budget pct now: ' || (SELECT "total_budget_percent_budgeted" FROM "budget" WHERE "School_id"=1 AND "Year"=2003));
  ROLLBACK;
  DBMS_OUTPUT.PUT_LINE('after ROLLBACK, Falcons location: ' || (SELECT "Location" FROM "School" WHERE "Mascot"='Falcons'));
END;

